39;de&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Humano&#239;de_monstrueux_15&quot;&gt;Humano&#239;de monstrueux&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Mort-vivant_16&quot;&gt;Mort-vivant&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Vase_17&quot;&gt;Vase&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Vermine_18&quot;&gt;Vermine&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Les_greffes_de_classe_39&quot;&gt;Les greffes de classe&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Classes_hybrides__0&quot;&gt; Classes hybrides &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Les_compagnons_animaux_et_les_montures__1&quot;&gt; Les compagnons animaux et les montures &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Alchimiste_19&quot;&gt;Alchimiste&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Barbare_20&quot;&gt;Barbare&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Barde_21&quot;&gt;Barde&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Chevalier_22&quot;&gt;Chevalier&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Conjurateur_23&quot;&gt;Conjurateur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Druide_24&quot;&gt;Druide&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Ensorceleur_25&quot;&gt;Ensorceleur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Les_options_de_lignage__2&quot;&gt; Les options de lignage &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Guerrier_26&quot;&gt;Guerrier&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Inquisiteur_27&quot;&gt;Inquisiteur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Magicien_28&quot;&gt;Magicien&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Les_options_des_&#233;coles_profanes__3&quot;&gt; Les options des &#233;coles profanes &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Magus_29&quot;&gt;Magus&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Moine_30&quot;&gt;Moine&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Oracle_31&quot;&gt;Oracle&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Les_options_de_myst&#232;res__4&quot;&gt; Les options de myst&#232;res &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Paladin_32&quot;&gt;Paladin&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pistolier_33&quot;&gt;Pistolier&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Pr&#234;tre_34&quot;&gt;Pr&#234;tre&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;small&gt;&lt;a href=&quot;#_Les_options_de_domaine__5&quot;&gt; Les options de domaine &lt;/a&gt;&lt;/small&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#R&#244;deur_35&quot;&gt;R&#244;deur&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Roublard_36&quot;&gt;Roublard&lt;/a&gt;&lt;br /&gt;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&amp;nbsp;&lt;a href=&quot;#Sorci&#232;re_37&quot;&gt;Sorci&#232;re&lt;/a&gt;&lt;br /&gt;&lt;/p&gt;&lt;/div&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;Avec le syst&#232;me normal de cr&#233;ation de monstres, les statistiques essentielles telles que le bonus de base &#224; l’attaque, les bonus de sauvegarde et les points de vie, sont calcul&#233;s d’apr&#232;s le type de cr&#233;ature et les niveaux de classe du monstre. Avec ce syst&#232;me, la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-1.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 1 : La gamme&quot;&gt;gamme&lt;/a&gt; du monstre fixe ses statistiques principales en fonction du r&#244;le g&#233;n&#233;ral et du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; qui le caract&#233;risent. Les types de cr&#233;ature et les classes ajustent ensuite ces statistiques afin qu’elles r&#233;pondent au mieux &#224; un concept de monstre particulier.&lt;br /&gt;&lt;br /&gt;Les types de cr&#233;ature et les classes de personnages sont illustr&#233;s via des &#171; greffes &#187; (des ensembles d’ajustements que l’on applique aux statistiques d’une gamme). Un monstre que l’on cr&#233;e avec ce syst&#232;me se d&#233;finit avant tout par son type ou sa classe de personnage. Par exemple, une goule qui est un puissant pr&#234;tre utilisera tr&#232;s certainement la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-2.html#PRETRE&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 2 : La greffe de type de cr&#233;ature ou de classe&quot;&gt;greffe de pr&#234;tre&lt;/a&gt; plut&#244;t que de se d&#233;finir principalement comme un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-2.html#MORTVIVANT&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 2 : La greffe de type de cr&#233;ature ou de classe&quot;&gt;mort-vivant&lt;/a&gt;. Un g&#233;ant du Feu avec 3 niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;barde&lt;/a&gt; devrait, quant &#224; lui, choisir la greffe de type &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-2.html#HUMANOIDE&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 2 : La greffe de type de cr&#233;ature ou de classe&quot;&gt;humano&#239;de&lt;/a&gt; et, plus tard, choisir quelques options de monstre lui accordant des pouvoirs de barde.&lt;br /&gt;&lt;br /&gt;Si le monstre se d&#233;finit d’abord par son type, choisissez la greffe de type qui convient et proc&#233;dez aux ajustements de greffe comme indiqu&#233; dans la section suivante. S’il se d&#233;finit d’abord par sa classe, choisissez une greffe de type mais appliquez uniquement les &#171; traits automatiques &#187; avant d’ajouter la greffe de classe. Par exemple, m&#234;me si un dragon poss&#232;de 20 niveaux de &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; (utilisant donc la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-2.html#ROUBLARD&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 2 : La greffe de type de cr&#233;ature ou de classe&quot;&gt;greffe de classe du roublard&lt;/a&gt;), il gagne quand m&#234;me les visions et immunit&#233;s normales du &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-2.html#DRAGON&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 2 : La greffe de type de cr&#233;ature ou de classe&quot;&gt;dragon&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Les greffes de type de cr&#233;ature&lt;a class=&quot;headeranchor&quot; id=&quot;Les_greffes_de_type_de_cr&#233;ature_38&quot; href=&quot;#Les_greffes_de_type_de_cr&#233;ature_38&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Alt&#233;rer une gamme avec un type de cr&#233;ature est un proc&#233;d&#233; simple qui, en g&#233;n&#233;ral, modifie certaines statistiques du monstre ou lui en rajoute. Chaque type de cr&#233;ature inclut au moins les deux premi&#232;res entr&#233;es parmi celles qui suivent.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; Toutes les cr&#233;atures de ce type gagnent ces pouvoirs qui, en principe, incluent les sens, les immunit&#233;s et les groupes de traits plus d&#233;taill&#233;s d&#233;finis dans la description compl&#232;te du &lt;a class=&quot;pagelink&quot; href=&quot;Types-De-Cr&#233;atures.html&quot; title=&quot;Les types et sous type de cr&#233;atures&quot;&gt;type de cr&#233;ature&lt;/a&gt;. Ceci n’inclut pas les modes de d&#233;placement ; cf. &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e.html#Les_autres_calculs_13&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e&quot;&gt;Vitesse de d&#233;placement&lt;/a&gt;, dans l&#39;&#201;tape 1.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ajustements de statistiques.&lt;/b&gt; Ces ajustements modifient les valeurs de base fix&#233;es par la gamme du monstre. Ce sont des ajustements, non pas des remplacements : augmentez ou r&#233;duisez du nombre indiqu&#233; les statistiques relev&#233;es pour la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-1.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 1 : La gamme&quot;&gt;gamme&lt;/a&gt;. Proc&#233;dez &#224; ces ajustements uniquement si votre monstre n’a pas de greffe de classe.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Ce sont des modifications optionnelles qui peuvent servir &#224; mieux illustrer le type du monstre et incluent fr&#233;quemment des changements dans la liste des comp&#233;tences, des options de monstre pour ce type de cr&#233;ature (cf. &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;&#201;tape 7&lt;/a&gt;) et des sorts, voire des limitations. Ces &#233;l&#233;ments devraient vous aiguiller vers des pouvoirs qui se manifestent, en g&#233;n&#233;ral, chez les cr&#233;atures du type indiqu&#233; mais ne repr&#233;sentent pas une liste exhaustive des possibilit&#233;s dont disposent les monstres de ce type.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Aberration&lt;a class=&quot;headeranchor&quot; id=&quot;Aberration_6&quot; href=&quot;#Aberration_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;L’aberration pr&#233;sente une anatomie bizarre, des pouvoirs &#233;tranges, une fa&#231;on de penser extraterrestre ou une combinaison de ces trois particularit&#233;s.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez le bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Sorts de la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#Aberrants&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;liste de sorts aberrants&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Animal&lt;a class=&quot;headeranchor&quot; id=&quot;Animal_7&quot; href=&quot;#Animal_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un animal est une cr&#233;ature non-humaine vivante qui ne poss&#232;de g&#233;n&#233;ralement pas de capacit&#233;s magiques ni aucune capacit&#233; inn&#233;e pour le langage.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;Vision nocturne&lt;/a&gt; ; r&#233;duisez le modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#224; -4 ou -5.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; de 2.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Cr&#233;ature artificielle&lt;a class=&quot;headeranchor&quot; id=&quot;Cr&#233;ature_artificielle_8&quot; href=&quot;#Cr&#233;ature_artificielle_8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une cr&#233;ature artificielle est un objet anim&#233; ou une cr&#233;ature que l’on a cr&#233;&#233;e artificiellement. La plupart poss&#232;dent une faible volont&#233; propre mais sont exceptionnellement r&#233;sistantes.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Type-Cr&#233;ature-Artificielle.html&quot; title=&quot;Cr&#233;ature artificielle&quot;&gt;immunit&#233;s des cr&#233;atures artificielles&lt;/a&gt; ; passez le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; &#224; —.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Diminuez les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de 2 ; augmentez le bonus d’attaque de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; D&#233;nu&#233; d’intelligence ; passez le modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#224; — pour les cr&#233;atures artificielles d&#233;nu&#233;es d’intelligence ; aucune comp&#233;tence profitable ou ma&#238;tris&#233;e.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Cr&#233;ature magique&lt;a class=&quot;headeranchor&quot; id=&quot;Cr&#233;ature_magique_9&quot; href=&quot;#Cr&#233;ature_magique_9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les cr&#233;atures magiques sont semblables aux animaux mais peuvent avoir une valeur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; sup&#233;rieure &#224; 2 (auquel cas la cr&#233;ature magique conna&#238;t au moins une langue mais ne sait pas forc&#233;ment parler). En outre, les cr&#233;atures magiques poss&#232;dent g&#233;n&#233;ralement des pouvoirs surnaturels ou extraordinaires.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; de 2 ; augmentez le bonus d’attaque de 2.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Dragon&lt;a class=&quot;headeranchor&quot; id=&quot;Dragon_10&quot; href=&quot;#Dragon_10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Un dragon est une cr&#233;ature reptilienne, g&#233;n&#233;ralement ail&#233;e, qui poss&#232;de des pouvoirs magiques ou inhabituels.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; ; immunis&#233; contre la paralysie et le sommeil.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez les bonus de sauvegarde minimaux de 2 ; augmentez le bonus d’attaque de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Option de combat &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Souffle&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;souffle&lt;/a&gt; (monstrueux) ; option universelle &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Magie secondaire&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;magie secondaire&lt;/a&gt; ; une comp&#233;tence ma&#238;tris&#233;e suppl&#233;mentaire.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Ext&#233;rieur&lt;a class=&quot;headeranchor&quot; id=&quot;Ext&#233;rieur_11&quot; href=&quot;#Ext&#233;rieur_11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;La plupart des ext&#233;rieurs sont des &#234;tres natifs d’un plan autre que le plan Mat&#233;riel ou des descendants mortels de ce genre de cr&#233;atures. Tous les ext&#233;rieurs sont constitu&#233;s, au moins en partie, de l’essence de leur plan d’origine. Certaines cr&#233;atures deviennent des ext&#233;rieurs quand elles atteignent un &#233;tat d’existence spirituelle sup&#233;rieur (ou inf&#233;rieur).
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez un bonus de sauvegarde de 2 ; augmentez le bonus d’attaque de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#Abyssaux&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;Sorts abyssaux&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#C&#233;lestes&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;c&#233;lestes&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#Infernaux&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;infernaux&lt;/a&gt; ; une comp&#233;tence ma&#238;tris&#233;e suppl&#233;mentaire.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;F&#233;e&lt;a class=&quot;headeranchor&quot; id=&quot;F&#233;e_12&quot; href=&quot;#F&#233;e_12&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les f&#233;es sont des cr&#233;atures surnaturelles qui tirent g&#233;n&#233;ralement leur puissance de leur lien ou de leur r&#244;le de gardien vis-&#224;-vis d’une r&#233;gion ou d’un site naturel. Les cr&#233;atures f&#233;eriques ressemblent &#224; des humains ou &#224; des gnomes mais il existe aussi des f&#233;es animales.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;Vision nocturne&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de 2 ; r&#233;duisez le bonus d’attaque de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Sorts de la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#F&#233;eriques&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;liste de sorts f&#233;eriques&lt;/a&gt; ; une comp&#233;tence ma&#238;tris&#233;e suppl&#233;mentaire.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Flore&lt;a class=&quot;headeranchor&quot; id=&quot;Flore_13&quot; href=&quot;#Flore_13&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ce type de cr&#233;atures comprend toutes les cr&#233;atures v&#233;g&#233;tales. Remarquez que les plantes normales, comme celles qui poussent dans les champs et les jardins, n’ont pas de valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sagesse&lt;/a&gt; ni de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; et ne sont pas consid&#233;r&#233;es comme des cr&#233;atures mais comme des objets, m&#234;me si elles sont vivantes.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;Vision nocturne&lt;/a&gt; ; &lt;a class=&quot;pagelink&quot; href=&quot;Type-Plante.html&quot; title=&quot;Plante&quot;&gt;immunit&#233;s des plantes&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez le bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Aucune comp&#233;tence ma&#238;tris&#233;e ou profitable.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Humano&#239;de&lt;a class=&quot;headeranchor&quot; id=&quot;Humano&#239;de_14&quot; href=&quot;#Humano&#239;de_14&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les humano&#239;des ont g&#233;n&#233;ralement deux bras, deux jambes et une t&#234;te, ou un torse, des bras et une t&#234;te humano&#239;des. Ils poss&#232;dent peu ou aucun pouvoir surnaturel ou extraordinaire mais la plupart peuvent parler et se caract&#233;risent par leurs soci&#233;t&#233;s tr&#232;s d&#233;velopp&#233;es. Ce sont g&#233;n&#233;ralement des cr&#233;atures de taille P ou M (&#224; l’exception des g&#233;ants). Chaque cr&#233;ature humano&#239;de poss&#232;de &#233;galement un &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-3.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 3 : La greffe de sous-type&quot;&gt;sous-type&lt;/a&gt; sp&#233;cifique qui correspond &#224; sa race, comme humain, g&#233;ant, gobelino&#239;de, reptilien ou tengu.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; Aucun.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez un bonus de sauvegarde de 2.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Humano&#239;de monstrueux&lt;a class=&quot;headeranchor&quot; id=&quot;Humano&#239;de_monstrueux_15&quot; href=&quot;#Humano&#239;de_monstrueux_15&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les humano&#239;des monstrueux sont semblables aux humano&#239;des mais pr&#233;sentent des traits pervertis ou animaux. Ils poss&#232;dent souvent des pouvoirs magiques.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de 2 ; augmentez le bonus d’attaque de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Une comp&#233;tence profitable suppl&#233;mentaire.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Mort-vivant&lt;a class=&quot;headeranchor&quot; id=&quot;Mort-vivant_16&quot; href=&quot;#Mort-vivant_16&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les morts-vivants sont d’anciennes cr&#233;atures vivantes que des forces surnaturelles ou spirituelles ont ramen&#233;es &#224; la vie.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres ; &lt;a class=&quot;pagelink&quot; href=&quot;Type-Mort-Vivant.html&quot; title=&quot;Mort-vivant&quot;&gt;immunit&#233;s des morts-vivants&lt;/a&gt;, passez le modificateur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt; &#224; —.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez le bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; D&#233;nu&#233; d’intelligence ; aucune comp&#233;tence ma&#238;tris&#233;e ou profitable ; passez le modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#224; — pour les morts-vivants d&#233;nu&#233;s d’intelligence.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Vase&lt;a class=&quot;headeranchor&quot; id=&quot;Vase_17&quot; href=&quot;#Vase_17&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une vase est une cr&#233;ature amorphe ou mutable g&#233;n&#233;ralement d&#233;pourvue de conscience. Les options dont elle dispose refl&#232;tent souvent sa composition physique et ses pouvoirs naturels divers.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Aveugl&#233;.html&quot; title=&quot;Aveugl&#233;&quot;&gt;Aveugle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Aveugle-(Capacit&#233;).html&quot; title=&quot;Vision aveugle (Ext)&quot;&gt;vision aveugle&lt;/a&gt; ; d&#233;nu&#233; d’intelligence, &lt;a class=&quot;pagelink&quot; href=&quot;Type-Vase.html&quot; title=&quot;Vase&quot;&gt;immunit&#233;s des vases&lt;/a&gt;, immunis&#233; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Actions-Simples#Coupcritique.html&quot; title=&quot;coup critique&quot;&gt;coups critiques&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat#Priseentenaille.html&quot; title=&quot;prise en tenaille&quot;&gt;prise en tenaille&lt;/a&gt; ; passez le modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#224; —.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez le bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; de 2, r&#233;duisez les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Aucune comp&#233;tence ma&#238;tris&#233;e ou profitable.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Vermine&lt;a class=&quot;headeranchor&quot; id=&quot;Vermine_18&quot; href=&quot;#Vermine_18&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Uniquement soucieuse de sa survie, la vermine se trouve dans presque tous les environnements. Ce type de cr&#233;atures inclut les insectes, les arachnides et autres arthropodes, les vers et invert&#233;br&#233;s similaires.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Traits automatiques.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;Vision dans le noir (Ext ou Sur)&quot;&gt;Vision dans le noir&lt;/a&gt; &#224; 18 m&#232;tres, d&#233;nu&#233; d’intelligence ; passez le modificateur d’&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt; &#224; —.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements automatiques.&lt;/b&gt; Augmentez le bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements optionnels.&lt;/b&gt; Aucune comp&#233;tence ma&#238;tris&#233;e ou profitable.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;GREFFESDECLASSE&quot; href=&quot;#GREFFESDECLASSE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les greffes de classe&lt;a class=&quot;headeranchor&quot; id=&quot;Les_greffes_de_classe_39&quot; href=&quot;#Les_greffes_de_classe_39&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;Les greffes de classe sont plus d&#233;taill&#233;es que les greffes de type car elles sont davantage repr&#233;sentatives d’une classe de PJ du niveau appropri&#233;. Chaque greffe de classe pr&#233;sente les sections suivantes.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;R&#232;gles sp&#233;ciales.&lt;/b&gt; Cette section n’appara&#238;t que dans certaines descriptions et indique les particularit&#233;s ou conditions requises importantes pour la classe.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Gamme requise.&lt;/b&gt; Quand vous cr&#233;ez un monstre de cette classe, vous devez utiliser une gamme sp&#233;cifique. C’est un exemple de greffe imposant une condition requise afin que le monstre r&#233;ponde au caract&#232;re particulier de la classe.&lt;br /&gt;&lt;br /&gt;Si vous souhaitez reproduire une classe sans utiliser la gamme indiqu&#233;e, n’utilisez pas la greffe de classe. Par exemple, si vous souhaitez cr&#233;er un monstre &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; issu de la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-1.html#COMBATTANT&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 1 : La gamme&quot;&gt;gamme de combattant&lt;/a&gt;, vous pouvez toujours illustrer le caract&#232;re particulier du pr&#234;tre en choisissant l’option de &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Magie secondaire&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;magie secondaire&lt;/a&gt; lors de l’&#201;tape 7. Le principe consiste pratiquement &#224; imiter un pr&#234;tre issu du syst&#232;me de cr&#233;ation normal et dot&#233; de dons de combat et de nombreux sorts lanc&#233;s en avance pour b&#233;n&#233;ficier de bonus de combat.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Ajustements de statistiques.&lt;/b&gt; Cette section modifie ou remplace certaines valeurs, comp&#233;tences et options de base indiqu&#233;es pour la gamme du monstre. Proc&#233;dez aux ajustements sp&#233;cifi&#233;s. Toute comp&#233;tence sp&#233;cifi&#233;e remplace l’une des comp&#233;tences que le monstre a choisies avec sa gamme (qu’il s’agisse d’une comp&#233;tence ma&#238;tris&#233;e ou profitable, selon ce qui est pr&#233;cis&#233;). Si un monstre gagne des comp&#233;tences suppl&#233;mentaires en plus du nombre normalement autoris&#233;, cette section pr&#233;cise &#171; une comp&#233;tence ma&#238;tris&#233;e suppl&#233;mentaire &#187; ou &#171; une comp&#233;tence profitable suppl&#233;mentaire. &#187; Il se peut &#233;galement que les ajustements signalent des options, qui viennent alors remplacer les options que le monstre gagne via sa gamme.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;FP.&lt;/b&gt; Ces ajustements reproduisent la progression selon le niveau. N’appliquez que l’entr&#233;e la plus &#233;lev&#233;e &#224; votre monstre : par exemple, un roublard de &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 3 r&#233;pondra &#224; la ligne FP 3 et non &#224; la ligne FP 1. Les options qu’apportent ces entr&#233;es remplacent celles que le monstre gagne gr&#226;ce &#224; sa gamme. Il est possible que la greffe de classe rajoute plus d’options que ne l’autorise sa gamme : ce n’est pas un probl&#232;me et, comme d’habitude, vous pouvez d&#233;cider d’ajouter ou de supprimer des options suppl&#233;mentaires si vous en avez besoin pour que le monstre fonctionne selon son th&#232;me. Consultez l’&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;&#201;tape 7&lt;/a&gt; pour la description de ces options.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Modificateurs de caract&#233;ristique sugg&#233;r&#233;s.&lt;/b&gt; Cette section indique l’ordre dans lequel il est recommand&#233; d’attribuer les diff&#233;rents bonus aux valeurs de caract&#233;ristique du monstre, du plus &#233;lev&#233; au plus bas. Par exemple, pour le &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-2.html#BARBARE&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 2 : La greffe de type de cr&#233;ature ou de classe&quot;&gt;barbare&lt;/a&gt;, il est indiqu&#233; &#171; Force, Constitution, Dext&#233;rit&#233; &#187;, ce qui signifie que, lorsque vous cr&#233;ez un barbare &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 1/2, vous devriez lui attribuer un modificateur de +3 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt;, un modificateur de +2 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;] et un modificateur de +1 en &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Options sugg&#233;r&#233;es.&lt;/b&gt; Cette section pr&#233;sente des exemples de situations dans lesquelles la gamme du monstre accorde des options de monstre suppl&#233;mentaires, en plus de celles qui sont d&#233;termin&#233;es par la greffe de classe. En g&#233;n&#233;ral, ces options reproduisent des options de classe de personnage assez flexibles, telles que les &lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#POUVOIRDERAGE&quot; title=&quot;Le barbare&quot;&gt;pouvoirs de rage&lt;/a&gt; du barbare ou les &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html#TALENTDUROUBLARD&quot; title=&quot;Le roublard&quot;&gt;talents du roublard&lt;/a&gt; (cf. &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;&#201;tape 7&lt;/a&gt;).&lt;br /&gt;&lt;br /&gt;&lt;b&gt;Listes de sorts sugg&#233;r&#233;es.&lt;/b&gt; Cette section ne concerne que les greffes de classe des monstres lanceurs de sorts et vous aiguille vers les listes de sorts qui correspondent le mieux aux sorts typiques de la classe.&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Classes hybrides&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Classes_hybrides__0&quot; href=&quot;#_Classes_hybrides__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Pour cr&#233;er un monstre qui imite une classe issue du Manuel des joueurs - Classes avanc&#233;es, utilisez une greffe de classe mais remplacez certaines de ses options par celles de la greffe de classe secondaire. Dans certains cas, il est plus facile d’utiliser une greffe de classe existante dans son ensemble pour ensuite la rapprocher d’une classe du Manuel des joueurs - Classes avanc&#233;es en choisissant les options de monstre appropri&#233;es. Utilisez la table suivante pour savoir laquelle utiliser pour chaque classe.&lt;br /&gt;&lt;br /&gt;&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Classe&lt;/td&gt;&lt;td&gt;Greffe&lt;br /&gt;principale&lt;/td&gt;&lt;td&gt;Greffe&lt;br /&gt;secondaire&lt;/td&gt;&lt;td&gt;Incantation&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arcaniste.html&quot; title=&quot;L&amp;#39;arcaniste&quot;&gt;Arcaniste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Magicien&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;Magicien&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanguin.html&quot; title=&quot;Le sanguin&quot;&gt;Sanguin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Barbare&lt;/td&gt;&lt;td&gt;Ensorceleur&lt;/td&gt;&lt;td&gt;Option de&lt;br /&gt;magie secondaire&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lutteur.html&quot; title=&quot;Le lutteur&quot;&gt;Lutteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Guerrier&lt;/td&gt;&lt;td&gt;Moine&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html&quot; title=&quot;Le chasseur&quot;&gt;Chasseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;R&#244;deur&lt;/td&gt;&lt;td&gt;Druide&lt;/td&gt;&lt;td&gt;Barde&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Enqu&#234;teur.html&quot; title=&quot;L&amp;#39;enqu&#234;teur&quot;&gt;Enqu&#234;teur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Alchimiste&lt;/td&gt;&lt;td&gt;Roublard&lt;/td&gt;&lt;td&gt;Alchimiste&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chaman.html&quot; title=&quot;Le chaman&quot;&gt;Chaman&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Sorci&#232;re&lt;/td&gt;&lt;td&gt;Oracle&lt;/td&gt;&lt;td&gt;Sorci&#232;re&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Scalde.html&quot; title=&quot;Le scalde&quot;&gt;Scalde&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Barde&lt;/td&gt;&lt;td&gt;Barbare&lt;/td&gt;&lt;td&gt;Barde&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tueur.html&quot; title=&quot;Le tueur&quot;&gt;Tueur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Roublard&lt;/td&gt;&lt;td&gt;R&#244;deur&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;Bretteur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Guerrier&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre-Combattant.html&quot; title=&quot;Le pr&#234;tre combattant&quot;&gt;Pr&#234;tre combattant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Guerrier&lt;/td&gt;&lt;td&gt;Pr&#234;tre&lt;/td&gt;&lt;td&gt;Inquisiteur&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;h4 class=&quot;separator&quot;&gt;&lt;u&gt;Les compagnons animaux et les montures&lt;/u&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Les_compagnons_animaux_et_les_montures__1&quot; href=&quot;#_Les_compagnons_animaux_et_les_montures__1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;Si vous d&#233;cidez qu’un monstre devrait avoir un compagnon animal ou une monture, choisissez un animal issu de la liste d’un sort de &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-Dalli&#233;s-Naturels-I.html&quot; title=&quot;Convocation d&amp;#39;alli&#233;s naturels I&quot;&gt;convocation d’alli&#233;s naturels&lt;/a&gt;. Le sort ne doit pas &#234;tre d’un niveau sup&#233;rieur &#224; la moiti&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; du monstre. Traitez le compagnon comme une cr&#233;ature suppl&#233;mentaire lors des rencontres, sa d&#233;faite apportant des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Pointsdexperience.html&quot; title=&quot;PX&quot;&gt;PX&lt;/a&gt; comme s’il s’agissait d’une cr&#233;ature ind&#233;pendante plut&#244;t que d’un compagnon animal.&lt;br /&gt;&lt;br /&gt;Sinon, vous pouvez aussi cr&#233;er un animal de A &#224; Z avec le syst&#232;me de cr&#233;ation de monstres simplifi&#233;. Le &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; de ce monstre ne doit alors pas d&#233;passer 1 + 1/2 &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; du monstre principal et la d&#233;faite du compagnon rapporte des &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Pointsdexperience.html&quot; title=&quot;PX&quot;&gt;PX&lt;/a&gt; comme s’il ne s’agissait pas d’un compagnon animal.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ALCHIMISTE&quot; href=&quot;#ALCHIMISTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Alchimiste&lt;a class=&quot;headeranchor&quot; id=&quot;Alchimiste_19&quot; href=&quot;#Alchimiste_19&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les alchimistes sont &#224; la crois&#233;e de la magie et de la science. Ils m&#233;langent des agents chimiques exotiques qu’ils impr&#232;gnent d’une puissance magique afin de cr&#233;er des effets inhabituels, parfois impr&#233;visibles.
&lt;ul&gt;&lt;li&gt;&lt;b&gt;R&#232;gles sp&#233;ciales.&lt;/b&gt; Les capacit&#233;s d’incantation qu’accorde cette greffe reproduisent les extraits que l’&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; fabrique. L’alchimiste doit se r&#233;f&#233;rer &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#Alchimie&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;liste des sorts de l’alchimie&lt;/a&gt;. De plus, les &#171; sorts &#187; que lance l’alchimiste comptent comme des effets surnaturels, non pas comme des sorts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Gamme requise.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-1.html#EXPERT&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 1 : La gamme&quot;&gt;Expert&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Ajustements de statistiques.&lt;/b&gt; Utilisez les bonus de sauvegarde indiqu&#233;s pour la &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-1.html#COMBATTANT&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 1 : La gamme&quot;&gt;gamme de combattant&lt;/a&gt; ; &lt;i&gt;comp&#233;tence&lt;/i&gt; – &lt;a class=&quot;pagelink&quot; href=&quot;Artisanat.html&quot; title=&quot;Artisanat&quot;&gt;Artisanat&lt;/a&gt; (alchimie) ma&#238;tris&#233; ; &lt;i&gt;options&lt;/i&gt; – &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Bombes&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;bombes&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Mutag&#232;ne&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;mutag&#232;ne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Magie secondaire&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;magie secondaire&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;FP 1.&lt;/b&gt; &lt;i&gt;Options&lt;/i&gt; – infusion d’&#233;nergie.&lt;/li&gt;&lt;li&gt;&lt;b&gt;FP 3.&lt;/b&gt; Remplacez magie secondaire par incantation (comme s’il s’agissait d’un FP 2) ; &lt;i&gt;options&lt;/i&gt; – infusion d’&#233;nergie, une option libre.&lt;/li&gt;&lt;li&gt;&lt;b&gt;FP 6.&lt;/b&gt; Remplacez magie secondaire par incantation (comme s’il s’agissait d’un FP 4) ; &lt;i&gt;options&lt;/i&gt; – infusion d’&#233;nergie, une option libre.&lt;/li&gt;&lt;li&gt;&lt;b&gt;FP 9.&lt;/b&gt; Remplacez magie secondaire par incantation (comme s’il s’agissait d’un FP 6) ; &lt;i&gt;options&lt;/i&gt; – infusion d’&#233;nergie, immunit&#233; (poison), une option libre.&lt;/li&gt;&lt;li&gt;&lt;b&gt;FP 12.&lt;/b&gt; Remplacez magie secondaire par incantation (comme s’il s’agissait d’un FP 8) ; &lt;i&gt;options&lt;/i&gt; – infusion d’&#233;nergie, immunit&#233; (poison), une option magique, une option libre.&lt;/li&gt;&lt;li&gt;&lt;b&gt;FP 15.&lt;/b&gt; Remplacez magie secondaire par incantation (comme s’il s’agissait d’un FP 10) ; &lt;i&gt;options&lt;/i&gt; – infusion d’&#233;nergie, immunit&#233; (poison), une option magique, une option libre.&lt;/li&gt;&lt;li&gt;&lt;b&gt;FP 18.&lt;/b&gt; Remplacez &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Magie secondaire&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;magie secondaire&lt;/a&gt; par incantation (comme s’il s’agissait d’un &lt;a class=&quot;pagelink&quot; href=&quot;Rencontres#Fp.html&quot; title=&quot;FP&quot;&gt;FP&lt;/a&gt; 12) ; &lt;i&gt;options&lt;/i&gt; – &lt;a class=&quot;pagelink&quot; href=&quot;Cr%C3%A9ation%20de%20monstres%20simplifi%C3%A9e,%20%C3%89tape%207.ashx#Infusion d&#39;&#233;nergie&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;infusion d’&#233;nergie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Immunit&#233;&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;immunit&#233;&lt;/a&gt; (poison), une &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#OPTIONSMAGIQUES&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;option magique&lt;/a&gt;, deux options libres.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;b&gt;Modificateurs de caract&#233;ristique sugg&#233;r&#233;s.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Intelligence&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Options sugg&#233;r&#233;es.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Attaque suppl&#233;mentaire&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;Attaque suppl&#233;mentaire&lt;/a&gt; (l’alchimiste peut utiliser ce pouvoir avec les &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Bombes&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;bombes&lt;/a&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Savant&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;savant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Poison&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;poison&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Incantation spontan&#233;e&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;incantation spontan&#233;e&lt;/a&gt; (soins), &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-7.html#Emplacement pi&#233;g&#233;&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 7 : Les options de monstre&quot;&gt;emplacement pi&#233;g&#233;&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Listes de sorts sugg&#233;r&#233;es.&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;ation-De-Monstres-Simplifi&#233;e,-&#201;tape-6.html#Alchimie&quot; title=&quot;Cr&#233;ation de monstres simplifi&#233;e, &#201;tape 6&quot;&gt;Alchimie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
